function shortestSuperstring(A) {
  let n = A.length;
  let overlaps = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i !== j) {
        for (let k = Math.min(A[i].length, A[j].length); k > 0; k--) {
          if (A[i].endsWith(A[j].substring(0, k))) {
            overlaps[i][j] = k; break;
          }
        }
      }
    }
  }
  return buildResult(overlaps, A);
}
